import concurrent.futures, json, urllib.request, xml.etree.ElementTree as ET
from html.parser import HTMLParser
from pathlib import Path
class Article(HTMLParser):
 def __init__(self): super().__init__(); self.depth=0; self.parts=[]
 def handle_starttag(self,t,a):
  if t=='article': self.depth+=1
  if self.depth and t in ('p','div','h1','h2','h3','li','tr','pre','br'): self.parts.append('\n')
 def handle_endtag(self,t):
  if t=='article': self.depth-=1
 def handle_data(self,d):
  if self.depth: self.parts.append(d)
r=ET.fromstring(urllib.request.urlopen('https://docs.0g.ai/sitemap.xml').read())
urls=[x.text for x in r.iter() if x.tag.endswith('loc') and ('/compute-network/' in x.text or x.text.endswith('/concepts/compute'))]
