cat > agent/lending_setup.py <<'EOF'
"""Review or execute the fixed testnet deployment from the existing encrypted agent wallet."""
import argparse
import asyncio
import json
from pathlib import Path

from agent.config import Config
from agent.runtime import Runtime


async def run(args):
    runtime = Runtime(Config())
    try:
        user = args.user
        if not user:
            rows = runtime.store.db.execute("SELECT user_id FROM wallets WHERE kind='local'").fetchall()
            if len(rows) != 1:
                raise ValueError("Select the existing authenticated user with --user; no wallet is created.")
            user = rows[0][0]
        owner = runtime.wallets.agent_wallet(user)["address"]
        payload = {"directory": str(Path(args.directory).resolve()), "owner": owner, "user": user,
                   "confirmation": args.execute}
        if args.execute:
            row = runtime.store.db.execute("SELECT secret FROM wallets WHERE user_id=? AND kind='local'", (user,)).fetchone()
            payload["key"] = runtime.wallets.vault.open(row[0], f"wallet:{user}")
        child = await asyncio.create_subprocess_exec(
            "node", "scripts/part4/setup.mjs", stdin=asyncio.subprocess.PIPE,
            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL)
        try:
            output, _ = await child.communicate(json.dumps(payload).encode())
        finally:
            payload.pop("key", None)
        print(output.decode())
        if child.returncode:
            raise SystemExit(child.returncode)
    finally:
        await runtime.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--user")
    parser.add_argument("--directory", default=".local/lending-agent-setup")
    parser.add_argument("--execute", help="Exact review hash. Without this flag only public deployment review is produced.")
    asyncio.run(run(parser.parse_args()))


if __name__ == "__main__":
    main()
